update public.assess_items set payload = payload || jsonb_build_object('passagesB', '[{"key": "A", "label": "Easier text (about Years 2 to 3)", "title": "The Lost Boat", "text": "Tom and his brother Ben went to the lake on a sunny afternoon. Tom had a new blue boat with a small white sail. He placed it on the water and gave it a gentle push. The boat sailed across the lake and bobbed over the ripples. Ben clapped his hands and cheered. Then a strong gust of wind caught the sail and the boat spun round. It drifted away from the bank towards the reeds. Tom and Ben ran along the path. They looked behind the rocks and under the little bridge. At last Ben pointed to the tall reeds. The boat was stuck in the mud, tipping from side to side. A kind woman with a long net helped them to pull it out. Tom thanked her and tied a string to the front of the boat. This time he would hold on tight.", "words": 146}, {"key": "B", "label": "Middle text (about Years 4 to 5)", "title": "The Night Train", "text": "Every Friday evening, as the sun began to set, the night train pulled out of the little station. Leo liked to stand on the footbridge and watch it leave. The platform smelled of coal smoke, and the signal lamps glowed red and green. His uncle had driven trains on this line for thirty years. He still came to the station each week, even though he had retired. Tonight he stood beside Leo with a paper bag of warm chestnuts. He pointed to the carriages one by one and told him where each one was going. The long silver train was going to the far north. As the whistle blew, the wheels began to turn slowly and the steam drifted into the sky. Leo took out his notebook and started to write down the numbers. Soon his family would be moving abroad, a long way from the railway. He did not know when he would see the station again. His uncle smiled and said that the trains would always keep running. Leo wrote down one last number and then closed the book.", "words": 181}, {"key": "C", "label": "Harder text (about Year 6 and above)", "title": "The Compass", "text": "On the morning the expedition left, the harbour was crowded with families waving flags and shouting farewells. Nora stood at the rail of the ship, clutching the small compass her grandmother had given her. The captain was a cautious man who rarely joined in the celebrations. He warned the crew that the voyage would be long, because the route north passed through dangerous waters. For many days, Nora did nothing except scrub the deck and carry supplies below. She wondered whether she would ever be trusted with a proper task. Then, one foggy night, the navigator fell ill and the ship drifted dangerously close to a hidden reef. The captain turned to Nora and asked her to read the compass aloud without delay. Her voice trembled as she called out the bearings. She took a deep breath and remembered everything she had learned from the old charts. Gradually, the ship swung away from the rocks. By dawn, the fog had lifted, and the open sea lay calm and silver before them. The captain studied her for a long moment, and then he shook her hand. It was the first time Nora felt like a real sailor.", "words": 196}]'::jsonb) where test_key='fluency';